package ai.taskforge.ai; import org.springframework.stereotype.Component; import java.time.*; import java.util.*; import java.util.regex.*;
@Component public class MockLlmProvider implements LlmProvider { public Analysis analyze(String text){String cleaned=text.replaceAll("\\s+"," ").trim(); var parts=cleaned.split("(?<=[.!?])\\s+");var actions=new ArrayList<ExtractedTask>();for(String part:parts){if(part.matches("(?i).*\\b(please|review|send|create|fix|approve|deploy|prepare|update|confirm)\\b.*")){String title=part.replaceFirst("(?i)^(please\\s+)?"," ").replaceAll("[.!?]$","").trim();actions.add(new ExtractedTask(title,part,"Operations",priority(cleaned),deadline(cleaned),"2h",List.of()));}}if(actions.isEmpty())actions.add(new ExtractedTask("Review request",cleaned,"Operations",priority(cleaned),deadline(cleaned),"1h",List.of()));int score=score(cleaned);return new Analysis(cleaned.length()>220?cleaned.substring(0,217)+"…":cleaned,"Operations",priority(cleaned),score,deadline(cleaned),List.of(),actions,List.of(score>=75?"Urgency or deadline language detected.":"No immediate urgency detected.",cleaned.toLowerCase().contains("client")?"Client-facing context increases impact.":"Priority is based on explicit request language."));} private int score(String s){s=s.toLowerCase();int x=50;if(s.matches(".*\\b(urgent|asap|critical|production)\\b.*"))x+=30;if(s.matches(".*\\b(today|tomorrow|friday)\\b.*"))x+=15;if(s.contains("client"))x+=10;return Math.min(x,100);} private String priority(String s){int v=score(s);return v>=90?"CRITICAL":v>=75?"HIGH":v>=40?"MEDIUM":"LOW";} private LocalDate deadline(String s){s=s.toLowerCase();if(s.contains("today"))return LocalDate.now();if(s.contains("tomorrow"))return LocalDate.now().plusDays(1);return null;} }
